INSERT INTO `task_node` VALUES ('演示任务', 'demo_job', 'default', 'default', null, null, 'import logging\n\ndef handler(*args, **kwargs):\n    \"\"\"演示任务：打印参数并返回执行摘要\"\"\"\n    logger = logging.getLogger(__name__)\n    logger.info(f\"演示任务执行中，参数: args={args}, kwargs={kwargs}\")\n    return {\n        \"status\": \"success\",\n        \"message\": \"演示任务执行成功\",\n        \"args_received\": len(args),\n        \"kwargs_keys\": list(kwargs.keys())\n    }\n', null, null, '0', '1', null, null, '0', '最简演示任务，用于验证调度器基本功能', '1', 'bf192ea1-7c93-4395-a633-d77c15df6293', '2026-06-21 17:56:34', '2026-06-21 17:56:34', null, '1', null, null);
INSERT INTO `task_node` VALUES ('数据库清理任务', 'db_cleanup', 'sqlalchemy', 'default', null, null, 'import logging\nfrom datetime import datetime, timedelta\n\ndef handler(*args, **kwargs):\n    \"\"\"清理过期数据：删除N天前的日志和临时数据\"\"\"\n    logger = logging.getLogger(__name__)\n    days = kwargs.get(\"days\", 90)\n    cutoff = datetime.now() - timedelta(days=days)\n    logger.info(f\"清理 {cutoff.strftime(\'%Y-%m-%d\')} 之前的过期数据...\")\n    return {\n        \"status\": \"success\",\n        \"cutoff_date\": cutoff.strftime(\"%Y-%m-%d %H:%M:%S\"),\n        \"deleted_count\": 0\n    }\n', null, '{\"days\": 30}', '1', '1', null, null, '0', '清理过期操作日志和临时数据，建议每天凌晨3点执行', '2', '3a3f2e3f-bc6e-4978-8244-c51e99306f1d', '2026-06-21 17:56:34', '2026-06-21 17:56:34', null, '1', null, null);
INSERT INTO `task_node` VALUES ('健康检查任务', 'health_check', 'default', 'default', null, null, 'import logging\nimport psutil\n\ndef handler(*args, **kwargs):\n    \"\"\"系统健康检查：采集 CPU、内存、磁盘使用率\"\"\"\n    logger = logging.getLogger(__name__)\n    cpu = psutil.cpu_percent(interval=1)\n    mem = psutil.virtual_memory()\n    disk = psutil.disk_usage(\"/\")\n    status = \"healthy\" if cpu < 80 and mem.percent < 90 and disk.percent < 90 else \"warning\"\n    logger.info(f\"健康检查: CPU={cpu}% MEM={mem.percent}% DISK={disk.percent}%\")\n    return {\n        \"status\": status,\n        \"cpu_percent\": cpu,\n        \"memory_percent\": mem.percent,\n        \"disk_percent\": disk.percent,\n        \"memory_total_gb\": round(mem.total / (1024**3), 1),\n        \"disk_total_gb\": round(disk.total / (1024**3), 1)\n    }\n', null, null, '1', '1', null, null, '0', '系统资源健康检查，建议每5分钟执行一次', '3', '8eea90c5-5bfd-48d7-a980-6d526a28ecfd', '2026-06-21 17:56:34', '2026-06-21 17:56:34', null, '1', null, null);
INSERT INTO `task_node` VALUES ('邮件批量发送', 'email_batch', 'sqlalchemy', 'default', null, null, 'import logging\n\ndef handler(*args, **kwargs):\n    \"\"\"批量发送待发送邮件\"\"\"\n    logger = logging.getLogger(__name__)\n    batch_size = kwargs.get(\"batch_size\", 50)\n    logger.info(f\"开始批量发送邮件，每批 {batch_size} 封...\")\n    return {\n        \"status\": \"success\",\n        \"sent_count\": 0,\n        \"failed_count\": 0,\n        \"batch_size\": batch_size\n    }\n', null, '{\"batch_size\": 50}', '0', '2', null, null, '0', '批量发送待发送邮件，建议每分钟执行一次', '4', '9ee948a2-7583-4d42-b2d3-18ffb3bb3aec', '2026-06-21 17:56:34', '2026-06-21 17:56:34', null, '1', null, null);
